function generate_digest(reg_type, reg_value_64bit):
    if reg_type == INT:
        // Trailing and leading run-lengths of identical bits (zeros or ones)
        trailing_cnt = count_trailing_zeros_or_ones(reg_value_64bit) & 0x3F
        leading_cnt  = count_leading_zeros_or_ones(reg_value_64bit) & 0x3F
        val_lsb6     = reg_value_64bit & 0x3F
        // 12-bit overlapping XOR-fold per Figure 6(a)
        digest = (trailing_cnt) ^ (leading_cnt << 3) ^ (val_lsb6 << 6)
        return digest & 0xFFF
    else if reg_type == FP:
        // Sign bit and high exponent bits right-aligned at bit 3 per Figure 6(b)
        digest = 0
        if is_fp16(reg_value_64bit):
            digest = (reg_value_64bit[15:13] & 0x7) << 3
        else if is_fp32(reg_value_64bit):
            digest = (reg_value_64bit[31:26] & 0x3F) << 3
        else: // FP64
            digest = (reg_value_64bit[63:55] & 0x1FF) << 3
        return digest & 0xFFF
    else if reg_type == FLAGS:
        // Condition code flags Value[3:0] replicated 3 times per Figure 6(c)
        f4 = reg_value_64bit & 0xF
        digest = f4 | (f4 << 4) | (f4 << 8)
        return digest & 0xFFF

function on_decode(inst):
    for dest_reg in inst.dest_registers:
        reg_table[dest_reg].valid = 0
        reg_table[dest_reg].payload = inst.rob_tag // 14-bit ROB index
        reg_table[dest_reg].decay_ctr = 256

function on_instruction_decoded_tick():
    // Decrement aging counter every instruction decoded
    for r = 0 to 64:
        if reg_table[r].valid == 1:
            if reg_table[r].decay_ctr > 0:
                reg_table[r].decay_ctr -= 1
            if reg_table[r].decay_ctr == 0:
                reg_table[r].valid = 0 // Invalidate stale digest

function on_execution_complete(rob_tag, dest_reg, value, reg_type):
    if reg_table[dest_reg].valid == 0 and reg_table[dest_reg].payload == rob_tag:
        reg_table[dest_reg].payload = generate_digest(reg_type, value)
        reg_table[dest_reg].valid = 1
        reg_table[dest_reg].decay_ctr = 256

function on_pipeline_squash(recover_rob_tag):
    // On mispredict recovery, in-flight instruction tags are flushed
    // Completed registers retain valid digests, enabling recovery-path correlation
    for r = 0 to 64:
        if reg_table[r].valid == 0:
            if is_younger_than_or_equal(reg_table[r].payload, recover_rob_tag):
                // Revert to invalid or architectural state
                reg_table[r].valid = 0

function predict_sR(PC):
    sR_sum = 0
    for b = 0 to 7:
        regs_in_bank = get_registers_for_bank(b)
        // Compute usefulness vector from UT0, UT1, UT2
        idx0 = Hash_UT0(PC) % 8
        idx1 = Hash_UT1(PC) % 8
        idx2 = Hash_UT2(PC) % 8

        max_u = -infinity
        best_reg = null
        for r in regs_in_bank:
            u_val = UT[b][0][idx0][r] + UT[b][1][idx1][r] + UT[b][2][idx2][r]
            if reg_table[r].valid == 1 and reg_table[r].decay_ctr > 0:
                if u_val > max_u:
                    max_u = u_val
                    best_reg = r

        if best_reg != null and max_u > 0:
            digest = reg_table[best_reg].payload[11:0]
            // Query WT0, WT1, WT2
            w0 = WT[b][0][Hash_WT0(PC, digest) % 512]
            w1 = WT[b][1][Hash_WT1(PC, digest) % 256]
            w2 = WT[b][2][Hash_WT2(PC, digest) % 128]
            bank_sum = w0 + w1 + w2
            // Scale bank output by 2.5 per Figure 5(c)
            sR_sum += int(bank_sum * 2.5)
        else:
            // Multiplier x0 if no valid register or non-positive usefulness
            sR_sum += 0

    return sR_sum

function update_sR(PC, actual_taken, sc_mispredicted, LSUM_abs, recorded_pred_state):
    // SC perceptron update condition: updated on misprediction or marginal confidence (|LSUM| <= Threshold)
    needs_update = sc_mispredicted or (LSUM_abs <= update_threshold)
    if not needs_update:
        return

    step = (actual_taken == 1) ? +1 : -1
    for b = 0 to 7:
        available_regs = recorded_pred_state.available_regs_per_bank[b]
        if length(available_regs) == 0:
            continue

        // 'If several registers were available within the same bank, it randomly selects one of them for the update'
        chosen_reg = select_random(available_regs)
        chosen_digest = recorded_pred_state.digests[chosen_reg]

        // Update WT0, WT1, WT2 for chosen digest
        idx_w0 = Hash_WT0(PC, chosen_digest) % 512
        idx_w1 = Hash_WT1(PC, chosen_digest) % 256
        idx_w2 = Hash_WT2(PC, chosen_digest) % 128
        WT[b][0][idx_w0] = sat_update_6bit(WT[b][0][idx_w0], step)
        WT[b][1][idx_w1] = sat_update_6bit(WT[b][1][idx_w1], step)
        WT[b][2][idx_w2] = sat_update_6bit(WT[b][2][idx_w2], step)

        // Update UT tables for chosen_reg
        // Usefulness incremented if the prediction from this bank aligned with actual outcome, decremented otherwise
        idx_u0 = Hash_UT0(PC) % 8
        idx_u1 = Hash_UT1(PC) % 8
        idx_u2 = Hash_UT2(PC) % 8
        u_step = (sign(WT[b][0][idx_w0] + WT[b][1][idx_w1] + WT[b][2][idx_w2]) == step) ? +1 : -1
        UT[b][0][idx_u0][chosen_reg] = sat_update_6bit(UT[b][0][idx_u0][chosen_reg], u_step)
        UT[b][1][idx_u1][chosen_reg] = sat_update_6bit(UT[b][1][idx_u1][chosen_reg], u_step)
        UT[b][2][idx_u2][chosen_reg] = sat_update_6bit(UT[b][2][idx_u2][chosen_reg], u_step)
